import Foundation
import XCTest

@testable import VaultKit

/// Interoperability with the reference implementation, byte for byte.
///
/// The fixture (`Fixtures/eth_ur_reference.json`) is generated by
/// `tools/interop/gen-eth-ur-fixture.cjs` from `@keystonehq/bc-ur-registry-eth` — the library
/// `@metamask/eth-qr-keyring` uses — so these tests compare the app against what a wallet
/// actually puts on the wire, not against the app's own encoder.
///
/// That distinction is the whole point. Both directions used to be wrong in the same way (an
/// outer CBOR tag that no wallet emits): the app's encoder wrote it, the app's decoder required
/// it, encode→decode round-tripped happily, and **every real MetaMask request was refused**.
/// A fixture from our own encoder could never have shown that (amendment 25).
final class EthURReferenceTests: XCTestCase {

    struct Reference: Decodable {
        struct Generator: Decodable {
            struct Libraries: Decodable {
                let keystoneEth: String
                let keystone: String
                let ngrave: String

                enum CodingKeys: String, CodingKey {
                    case keystoneEth = "@keystonehq/bc-ur-registry-eth"
                    case keystone = "@keystonehq/bc-ur-registry"
                    case ngrave = "@ngraveio/bc-ur"
                }
            }
            let script: String
            let libraries: Libraries
        }
        struct Request: Decodable {
            struct Inputs: Decodable {
                let requestId: String
                let signData: String
                let dataType: UInt64
                let path: [UInt32]
                let hardened: [Bool]
                let sourceFingerprint: String
                let chainId: UInt64
                /// The signature fixture's inputs, recorded beside the request's because one
                /// generator produced both.
                let signature: String
                let origin: String
            }
            let inputs: Inputs
            let ur: String
            let cborHex: String
        }
        struct Signature: Decodable {
            let ur: String
            let cborHex: String
        }
        let note: String
        let generator: Generator
        let outerTag: String
        let request: Request
        let signature: Signature
    }

    private func reference() throws -> Reference {
        let data = try FixtureLoader.data("eth_ur_reference", extension: "json")
        return try JSONDecoder().decode(Reference.self, from: data)
    }

    /// The fact the whole file rests on: the reference emits no outer tag.
    func testTheReferenceEmitsNoOuterCBORTag() throws {
        let fixture = try reference()
        XCTAssertEqual(fixture.outerTag, "absent")
        for hex in [fixture.request.cborHex, fixture.signature.cborHex] {
            XCTAssertNotEqual(
                try Hex.decode(hex).prefix(1), [0xd9],
                "0xd9 is the start of a CBOR tag: the payload is tagged after all"
            )
        }
        // And the app agrees: decoding yields a bare map.
        let request = try EthSignRequest(ur: try UR(urString: fixture.request.ur))
        XCTAssertEqual(request.chainID, EVMQuantity(fixture.request.inputs.chainId))
        XCTAssertNil(
            request.cbor().taggedValue,
            "the app must decode an untagged payload: no wallet tags these"
        )
    }

    // MARK: - Reading a wallet's request

    /// The reported bug, as a test: this exact UR string is what a wallet displays, and it must
    /// decode to the fields the wallet meant.
    func testDecodesARequestProducedByTheReferenceImplementation() throws {
        let fixture = try reference()
        let ur = try UR(urString: fixture.request.ur)
        XCTAssertEqual(ur.type, EthSignRequest.urType)
        let request = try EthSignRequest(ur: ur)

        XCTAssertEqual(request.requestID, try Hex.decode(fixture.request.inputs.requestId))
        XCTAssertEqual(request.signData, try Hex.decode(fixture.request.inputs.signData))
        XCTAssertEqual(request.dataType, .typedTransaction)
        XCTAssertEqual(request.chainID, EVMQuantity(fixture.request.inputs.chainId))
        XCTAssertNil(request.address, "MetaMask sends no address for a transaction")
        XCTAssertEqual(request.origin, nil)
        XCTAssertEqual(DerivationPath(components: request.derivationPath.components).description,
                       "m/44'/0'/0'/0/0")
        XCTAssertEqual(request.derivationPath.sourceFingerprint, 0x5436_d724)

        // And the transaction parses, which is what makes it signable at all.
        let transaction = try EVMTransaction(signData: request.signData, dataType: request.dataType)
        XCTAssertEqual(transaction.chainId, EVMQuantity(137))
        XCTAssertEqual(transaction.kind, .feeMarket)
        XCTAssertEqual(transaction.valueInEther, "1.5")
    }

    /// The app's encoder must produce the same bytes as the reference for the same inputs —
    /// otherwise the DEBUG sample exercises a shape no wallet sends, which is how the missing
    /// tag hid for a whole release.
    func testOurRequestEncodingMatchesTheReferenceByteForByte() throws {
        let fixture = try reference()
        let inputs = fixture.request.inputs
        let components = inputs.path.enumerated().map { index, value in
            inputs.hardened[index]
                ? DerivationPath.Component.hardened(value)
                : DerivationPath.Component.normal(value)
        }
        let fingerprintBytes = try Hex.decode(inputs.sourceFingerprint)
        let fingerprint = fingerprintBytes.reduce(UInt32(0)) { ($0 << 8) | UInt32($1) }
        let path = URKeyPath(
            path: DerivationPath(components: components),
            sourceFingerprint: fingerprint
        )
        let request = EthSignRequest(
            requestID: try Hex.decode(inputs.requestId),
            signData: try Hex.decode(inputs.signData),
            dataType: try XCTUnwrap(EVMSignDataType(rawValue: inputs.dataType)),
            chainID: EVMQuantity(inputs.chainId),
            derivationPath: path,
            address: nil,
            origin: nil
        )
        XCTAssertEqual(
            Hex.encode(request.cbor().cborData),
            fixture.request.cborHex,
            "the app's request bytes differ from the reference's"
        )
        // The UR string must match too: same bytes, same bytewords, same fragment count.
        XCTAssertEqual(try request.ur().string, fixture.request.ur)
    }

    // MARK: - Producing a signature the wallet can read

    /// MetaMask reads the signature as `ETHSignature`: numeric fields 1 (request id, tagged 37),
    /// 2 (`r‖s‖v`) and 3 (origin), in an untagged map. This pins our bytes to the reference's.
    func testOurSignatureEncodingMatchesTheReferenceByteForByte() throws {
        let fixture = try reference()
        let signature = try EthSignature(
            requestID: try Hex.decode(fixture.request.inputs.requestId),
            signature: try Hex.decode(fixture.request.inputs.signature),
            origin: fixture.request.inputs.origin
        )
        XCTAssertEqual(
            Hex.encode(signature.cbor().cborData),
            fixture.signature.cborHex,
            "the app's signature bytes differ from the reference's"
        )
        XCTAssertEqual(try signature.ur().string, fixture.signature.ur)
    }

    /// MetaMask's own reader (`ETHSignature.fromCBOR` in `@metamask/eth-qr-keyring`) requires
    /// field 1 to carry the request id and throws "Signature request ID is missing" without it —
    /// so this reads the committed bytes back the way the wallet does.
    func testTheReferenceSignatureCarriesWhatMetaMaskRequires() throws {
        let fixture = try reference()
        let cbor = try CBOR(try Hex.decode(fixture.signature.cborHex))
        let map = try XCTUnwrap(cbor.mapValue)
        let requestID = try XCTUnwrap(map.first { $0.key.unsignedValue == 1 }?.value)
        XCTAssertEqual(requestID.taggedValue?.tag, 37, "the request id is a tagged uuid")
        XCTAssertEqual(
            [UInt8](try XCTUnwrap(requestID.taggedValue?.value.bytesValue)),
            try Hex.decode(fixture.request.inputs.requestId)
        )
        let rsv = try XCTUnwrap(map.first { $0.key.unsignedValue == 2 }?.value.bytesValue)
        XCTAssertEqual([UInt8](rsv), try Hex.decode(fixture.request.inputs.signature))
    }

    /// The app's own decoder reads that shape too, so the round trip is meaningful.
    func testDecodesASignatureProducedByTheReferenceImplementation() throws {
        let fixture = try reference()
        let signature = try EthSignature(ur: try UR(urString: fixture.signature.ur))
        XCTAssertEqual(signature.requestID, try Hex.decode(fixture.request.inputs.requestId))
        XCTAssertEqual(signature.signature, try Hex.decode(fixture.request.inputs.signature))
        XCTAssertEqual(signature.origin, fixture.request.inputs.origin)
        XCTAssertEqual(signature.r.count, 32)
        XCTAssertEqual(signature.recoveryValueBytes.count, 1)
    }

    /// The recorded provenance, so a future reader knows what these bytes are.
    func testTheFixtureRecordsWhereItsBytesCameFrom() throws {
        let fixture = try reference()
        XCTAssertTrue(fixture.note.contains("reference implementation"))
        XCTAssertEqual(fixture.generator.libraries.keystoneEth, "0.22.1")
        XCTAssertTrue(fixture.generator.script.hasSuffix("gen-eth-ur-fixture.cjs"))
    }
}
